#[derive(Debug, Clone)]
struct Complex {
    real: i32,
    imaginary: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    const EPSILON: i32 = 2; // Fixed machine epsilon

    // Check if all imaginary parts are close to zero
    let all_close_to_zero = arr.iter().all(|c| {
        (c.imaginary.abs() <= tol * EPSILON)
    });

    if all_close_to_zero {
        // Create a new array with imaginary parts set to zero
        arr.iter().map(|c| Complex {
            real: c.real,
            imaginary: 0,
        }).collect()
    } else {
        // Return the input array unchanged
        arr
    }
}

fn main() {
    // Example usage
    let complex_numbers = vec![
        Complex { real: 1, imaginary: 0 },
        Complex { real: 2, imaginary: 1 },
        Complex { real: 3, imaginary: 1 },
    ];
    let tolerance = 1;

    let result = real_if_close(complex_numbers, tolerance);
    for c in result {
        println!("Complex: {} + {}i", c.real, c.imaginary);
    }
}